CREATE TABLE IF NOT EXISTS "approval" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "audit_log" (
  "log_id" integer GENERATED BY DEFAULT AS IDENTITY,
  "Timestamp" varchar(255) DEFAULT NULL,
  "id_log" varchar(255) DEFAULT NULL,
  "Action" varchar(255) DEFAULT NULL,
  "TableName" varchar(255) DEFAULT NULL,
  "UserID" varchar(255) DEFAULT NULL,
  "SQLQuery" text DEFAULT NULL,
  "ServerIP" varchar(255) DEFAULT NULL,
  "RequestURL" varchar(255) DEFAULT NULL,
  "RequestData" text DEFAULT NULL,
  "RequestCompleted" varchar(255) DEFAULT NULL,
  "RequestMsg" varchar(255) DEFAULT NULL,
  PRIMARY KEY ("log_id")
);

CREATE TABLE IF NOT EXISTS "kategori" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "korelasi_id" integer NOT NULL,
  "kategori" varchar(255) NOT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "klasifikasi" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "nama" varchar(255) DEFAULT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "korelasi" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "nama" varchar(255) NOT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "mesin" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "nama_mesin" varchar(255) DEFAULT NULL,
  "nomor_seri" varchar(50) DEFAULT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "roles" (
  "role_id" integer GENERATED BY DEFAULT AS IDENTITY,
  "role_name" varchar(255) NOT NULL,
  PRIMARY KEY ("role_id")
);

CREATE TABLE IF NOT EXISTS "tb_mesin_sig" (
  "id_sig" integer GENERATED BY DEFAULT AS IDENTITY,
