CREATE TABLE IF NOT EXISTS "tag" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "kategori_tag" varchar(255) NOT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "users" (
  "id_user" integer GENERATED BY DEFAULT AS IDENTITY,
  "nama" varchar(255) NOT NULL,
  "email" varchar(255) NOT NULL,
  "username" varchar(255) NOT NULL,
  "area" varchar(255) DEFAULT NULL,
  "mesin" varchar(255) DEFAULT NULL,
  "password" varchar(255) DEFAULT NULL,
  "login_session_key" varchar(255) DEFAULT NULL,
  "email_status" varchar(255) DEFAULT NULL,
  "password_expire_date" date DEFAULT NULL,
  "password_reset_key" varchar(255) DEFAULT NULL,
  "account_status" varchar(255) DEFAULT 'Pending',
  "user_role_id" integer DEFAULT NULL,
  "pict" varchar(255) DEFAULT NULL,
  "failed_login_attempts" integer DEFAULT 0,
  "is_super_admin" boolean NOT NULL DEFAULT false,
  PRIMARY KEY ("id_user")
);
-- Cuma boleh ada 1 baris is_super_admin=true di seluruh tabel -- dijaga di
-- level DB, bukan cuma diasumsikan lewat kode. Lihat
-- database/migrations/2026-08-20_add_super_admin_protection.sql.
CREATE UNIQUE INDEX IF NOT EXISTS "uq_users_single_super_admin"
  ON "users" ((is_super_admin))
  WHERE is_super_admin = true;

